const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: webhookData.body.model || 'text-embedding-3-small'
        }
      }
    };
  }

  try {
    const data = item.json.data || [];
    const embeddings = data.map(d => ({
      index: d.index,
      embedding: d.embedding,
      dimensions: d.embedding?.length || 0
    }));

    return {
      json: {
        success: true,
        data: {
          embeddings: embeddings,
          count: embeddings.length,
          model: item.json.model,
          dimensions: embeddings[0]?.dimensions || 0
        },
        meta: {
          provider: 'openai',
          model: item.json.model || webhookData.body.model || 'text-embedding-3-small',
          usage: item.json.usage || {}
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse embeddings response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          model: webhookData.body.model || 'text-embedding-3-small'
        }
      }
    };
  }
});

return results;
